/* eslint-disable @stencil-community/required-jsdoc */
import { Component, ComponentInterface, Element, Host, Prop, h } from '@stencil/core';
import { DateGridItem, DatePickerViewMode } from '../../../types';
import classNames from 'classnames';
import type { Dayjs } from 'dayjs';
import { computed, memoizedCallback } from '@src/shared/perf/cache';
import { isOutsidePeriod, mergeDateByUnit, startOfPeriod } from '../../../utils';
import { findSubViewMode, getViewModeConfig } from '../../../view-modes';
import { globalConfigStore } from '@src/shared/stores';

const prefix = 'date-grid-body';

type DateGridDateItemInfoInfo = DateGridItem & {
  type: 'date';
  isDisabled: boolean;
  isSelected: boolean;
  isRangeBetween: boolean;
  isOutsideCurrentPeriod: boolean;
  isNow: boolean;
  isRangeStart: boolean;
  isRangeEnd: boolean;
  shouldFlipStartAndEndDates: boolean;
  shouldClearEndDate: boolean;
};

@Component({
  tag: 'ks-date-time-picker-date-grid-body',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerDateGridBody implements ComponentInterface {
  @Element() el!: HTMLKsDateTimePickerDateGridBodyElement;

  @Prop() viewDate!: Dayjs;
  @Prop() viewMode!: DatePickerViewMode;
  @Prop() availableViewModes!: DatePickerViewMode[];

  /** If true, the presenter will display two input fields for a range. If false, a single input field is displayed. */
  @Prop() isRange!: boolean;
  @Prop() value!: [Dayjs | null, Dayjs | null];
  @Prop() now!: Dayjs;
  @Prop() disabledDate!: (
    date: Dayjs,
    info: { type: 'date' | 'preset'; from?: Dayjs; to?: Dayjs; selectionPhase?: 'start' | 'end' },
  ) => boolean;

  @Prop() presetPreviewDate!: [Dayjs | null, Dayjs | null] | null;
  @Prop() disabled!: [boolean, boolean];
  @Prop() selectionPhase!: 'start' | 'end' | 'idle';

  @Prop() hoverValue!: Dayjs | null;
  @Prop() handleHoverValueChange!: (value: Dayjs | null, hoverPart: 'start' | 'end' | null) => void;

  @Prop() handleValueChange!: (value: [Dayjs | null, Dayjs | null]) => void;
  @Prop() handleViewChange!: (viewDate: Dayjs, viewMode: DatePickerViewMode) => void;

  private get locale() {
    return globalConfigStore.state.locale;
  }

  private get viewModeConfig() {
    return getViewModeConfig(this.viewMode);
  }

  private getSubViewMode = computed(
    (currentViewMode: this['viewMode'], availableViewModes: this['availableViewModes']) =>
      findSubViewMode(currentViewMode, availableViewModes),
  );

  private get previewValue() {
    if (this.presetPreviewDate) {
      return this.presetPreviewDate;
    }

    const isMostGranularViewMode = !this.getSubViewMode(this.viewMode, this.availableViewModes);

    let previewValue = [...this.value];
    if (
      isMostGranularViewMode &&
      this.hoverValue &&
      this.selectionPhase !== 'idle' &&
      !(this.selectionPhase === 'start' && this.hoverValue.isAfter(previewValue[1]))
    ) {
      previewValue[this.selectionPhase === 'start' ? 0 : 1] = this.hoverValue;
    }
    if (previewValue[0] && previewValue[1] && previewValue[0].isAfter(previewValue[1])) {
      previewValue = [previewValue[1], previewValue[0]];
    }
    return previewValue;
  }

  private get isSelectingStartValue() {
    return this.selectionPhase === 'start' || (this.selectionPhase === 'idle' && !this.disabled[0]);
  }
  private getDateGridDateItemInfoInfo = (item: DateGridItem & { type: 'date' }): DateGridDateItemInfoInfo => {
    const { unit, period } = this.viewModeConfig;

    // should flip the start and end dates if they are in reverse order
    const shouldFlipStartAndEndDates =
      this.isRange &&
      !this.disabled[0] &&
      !this.disabled[1] &&
      !this.isSelectingStartValue &&
      item.value.isBefore(this.value[0], unit);
    const shouldClearEndDate =
      this.isRange &&
      !this.disabled[0] &&
      !this.disabled[1] &&
      this.isSelectingStartValue &&
      item.value.isAfter(this.value[1], unit);
    const isSelectingStartValue = shouldFlipStartAndEndDates ? !this.isSelectingStartValue : this.isSelectingStartValue;

    const startDate = this.previewValue[0];
    const endDate = this.previewValue[1];

    const isSameAsStartDate = item.value.isSame(startDate, unit);
    const isSameAsEndDate = item.value.isSame(endDate, unit);
    const isSelected = isSelectingStartValue
      ? isSameAsStartDate && (!endDate || isSameAsEndDate)
      : isSameAsEndDate && (!startDate || isSameAsStartDate);

    const isDisabled =
      this.disabledDate(item.value, {
        type: 'date',
        from: (!isSelectingStartValue && this.value[0]) || undefined,
        to:
          (isSelectingStartValue &&
            (shouldFlipStartAndEndDates ? this.value[0] : shouldClearEndDate ? undefined : this.value[1])) ||
          undefined,
        selectionPhase: this.isSelectingStartValue ? 'start' : 'end',
      }) ||
      (this.disabled[0] && item.value.isBefore(this.value[0])) ||
      (this.disabled[1] && item.value.isAfter(this.value[1]));

    const isRangeBetween =
      this.isRange &&
      Boolean(startDate && endDate && item.value.isAfter(startDate, unit) && item.value.isBefore(endDate, unit));
    const isOutsideCurrentPeriod = isOutsidePeriod(item.value, this.viewDate, period);

    return {
      ...item,
      isDisabled,
      isOutsideCurrentPeriod,
      isNow: item.value.isSame(this.now, unit),
      isSelected,
      isRangeStart: !isSelected && isSameAsStartDate,
      isRangeBetween,
      isRangeEnd: !isSelected && isSameAsEndDate,
      shouldFlipStartAndEndDates,
      shouldClearEndDate,
    };
  };

  private handleItemClick = memoizedCallback((item: DateGridDateItemInfoInfo) => {
    if (item.isDisabled) {
      return;
    }

    const subViewMode = this.getSubViewMode(this.viewMode, this.availableViewModes);
    if (subViewMode) {
      this.handleViewChange(item.value, subViewMode);
    } else {
      if (item.isOutsideCurrentPeriod) {
        // Also navigate the viewDate to the period of the clicked date if it's outside current period
        this.handleViewChange(startOfPeriod(item.value, this.viewModeConfig.period), this.viewMode);
      }

      let newValue: (typeof this)['value'];
      if (this.isSelectingStartValue) {
        newValue = [mergeDateByUnit(this.value[0], item.value, this.viewModeConfig.unit), this.value[1]];
      } else {
        newValue = [this.value[0], mergeDateByUnit(this.value[1], item.value, this.viewModeConfig.unit)];
      }
      if (item.shouldClearEndDate) {
        newValue[1] = null;
      } else if (item.shouldFlipStartAndEndDates) {
        newValue = [newValue[1], newValue[0]];
      }
      this.handleValueChange(newValue);
    }
  });

  private handlePointerEnter = memoizedCallback((item: DateGridDateItemInfoInfo) => {
    if (item.isDisabled) {
      return;
    }
    this.handleHoverValueChange(item.value, this.isSelectingStartValue ? 'start' : 'end');
  });
  private handlePointerLeave = () => {
    this.handleHoverValueChange(null, null);
  };

  private renderGridItem(item: DateGridItem) {
    if (item.type === 'indicator') {
      return (
        <div
          class={`${prefix}__decorative-header-item`}
          key={item.label}
          data-testid={`date-grid-index-2uxznc-${item.label}`}
        >
          {item.label}
        </div>
      );
    }
    if (item.type === 'date') {
      const dateGridDateItemInfo = this.getDateGridDateItemInfoInfo(item);

      return (
        <div
          key={item.label}
          class={classNames(`${prefix}__date-item`, {
            [`${prefix}__date-item--disabled`]: dateGridDateItemInfo.isDisabled,
            [`${prefix}__date-item--now`]: dateGridDateItemInfo.isNow,
            [`${prefix}__date-item--selected`]: dateGridDateItemInfo.isSelected,
            [`${prefix}__date-item--range-start`]: dateGridDateItemInfo.isRangeStart,
            [`${prefix}__date-item--range-between`]: dateGridDateItemInfo.isRangeBetween,
            [`${prefix}__date-item--range-end`]: dateGridDateItemInfo.isRangeEnd,
            [`${prefix}__date-item--outside-current-period`]: dateGridDateItemInfo.isOutsideCurrentPeriod,
          })}
          onClick={this.handleItemClick(dateGridDateItemInfo)}
          onPointerEnter={this.handlePointerEnter(dateGridDateItemInfo)}
          onPointerLeave={this.handlePointerLeave}
          data-testid={`body-index-dk47TM-${item.label}`}
        >
          {item.label}
        </div>
      );
    }
  }
  render() {
    const dateGridItems = this.viewModeConfig.generateDateGridItems(this.viewDate, this.locale);
    const rows = Math.max(
      this.viewModeConfig.minRows || 0,
      Math.ceil(dateGridItems.length / this.viewModeConfig.columns),
    );

    return (
      <Host>
        <div
          class={classNames(`${prefix}`, {
            [`${prefix}--compact-vertical-gap`]: this.viewModeConfig.compactVerticalGap,
          })}
          style={{
            gridTemplateColumns: `repeat(${this.viewModeConfig.columns}, 1fr)`,
            gridTemplateRows: `repeat(${rows}, 1fr)`,
          }}
        >
          {dateGridItems.map((item) => this.renderGridItem(item))}
        </div>
      </Host>
    );
  }
}
